#!/bin/bash

 # Sends all requests to web/maintenance.html with status 503.
 #
 # Adds or removes a marked block at the top of web/.htaccess. The file is
 # generated by composer scaffolding, so composer install also removes the
 # block.
 #
 # Usage: scripts/maintenance.sh on|off

 # Exit on error.
 set -e

 # Navigate to project root.
 SCRIPT_PATH="$( cd -- "$(dirname "$0")" || exit >/dev/null 2>&1 ; pwd -P )"
 cd "$SCRIPT_PATH/.." || exit
 HTACCESS=web/.htaccess
 BEGIN="# BEGIN maintenance"
 END="# END maintenance"

 [[ -f $HTACCESS ]] || { echo "Error: $HTACCESS is missing."; exit 1; }

 # Remove an existing block.
 TMP=$(mktemp)
 awk -v begin="$BEGIN" -v end="$END" '$0 == begin { skip = 1 } !skip { print } $0 == end { skip = 0 }' $HTACCESS > "$TMP"

 case "$1" in
  on)
   {
    cat <<'BLOCK'
# BEGIN maintenance
ErrorDocument 503 /maintenance.html
<IfModule mod_rewrite.c>
  RewriteEngine on
  RewriteCond %{REQUEST_URI} !=/maintenance.html
  RewriteRule ^ - [R=503,L]
</IfModule>
<IfModule mod_headers.c>
  Header always set Retry-After "3600"
  Header always set Cache-Control "no-store"
</IfModule>
# END maintenance
BLOCK
    cat "$TMP"
   } > $HTACCESS
   echo "Maintenance mode on."
   ;;
  off)
   cat "$TMP" > $HTACCESS
   echo "Maintenance mode off."
   ;;
  *)
   echo "Usage: $0 on|off"
   rm -f "$TMP"
   exit 1
   ;;
 esac
 rm -f "$TMP"
